  "gr-1jn5-13": "~45~4e~cc~ba ~22~7e ~a9~48 ~2c~48 ~27~44~44~c1 ~a9~d2 ~41~31~32~46~2f ~a9~d2 ~46~27~45 ~7e~31 ~27~cc~45~27~46 ~31~a9~be~2a~d2 ~c1~cc~ba ~27~50~33 ~44~26~d2 ~44~a9~be ~31~c1~27 ~c1~48~ba ~a9~c1 ~22~7e ~2c~27~46 ~44~cc~ba ~a9~c1 ~22~7e ~a9~48 ~27~28~2f~cc ~32~46~2f~af~cc ~2d~27~35~44 ~c1~d2~d4",
  "gr-rom8-1": "~27~28 ~2c~48 ~45~33~cc~2d ~39~cc~33~cc~70 ~45~cc~ba ~c1~cc~ba ~27~4f~46~c1~cc~ba ~45~2c~31~45 ~46~c1~cc~ba ~79~be~c1~31~27~cc~27 ~2c~27~2a~27~d4",
