export const B2_RVR: Record<string, string> = {
  "jes-jhn1-1": "EN el principio era el Verbo, y el Verbo era con Dios, y el Verbo era Dios.",
  "jes-jhn1-14": "Y aquel Verbo fu\u{e9} hecho carne, y habit\u{f3} entre nosotros (y vimos su gloria, gloria como del unig\u{e9}nito del Padre), lleno de gracia y de verdad.",
  "jes-isa9-6": "Porque un ni\u{f1}o nos es nacido, hijo nos es dado; y el principado sobre su hombro: y llamar\u{e1}se su nombre Admirable, Consejero, Dios fuerte, Padre eterno, Pr\u{ed}ncipe de paz.",
  "jes-col1-15": "El cual es la imagen del Dios invisible, el primog\u{e9}nito de toda criatura.",
  "jes-col1-17": "Y \u{e9}l es antes de todas las cosas, y por \u{e9}l todas las cosas subsisten:",
  "jes-heb1-3": "El cual siendo el resplandor de su gloria, y la misma imagen de su sustancia, y sustentando todas las cosas con la palabra de su potencia, habiendo hecho la purgaci\u{f3}n de nuestros pecados por s\u{ed} mismo, se sent\u{f3} \u{e1} la diestra de la Majestad en las alturas,",
  "jes-php2-8": "Y hallado en la condici\u{f3}n como hombre, se humill\u{f3} \u{e1} s\u{ed} mismo, hecho obediente hasta la muerte, y muerte de cruz.",
  "jes-php2-10": "Para que en el nombre de Jes\u{fa}s se doble toda rodilla de los que est\u{e1}n en los cielos, y de los que en la tierra, y de los que debajo de la tierra;",
  "jes-mat16-16": "Y respondiendo Sim\u{f3}n Pedro, dijo: T\u{fa} eres el Cristo, el Hijo del Dios viviente.",
  "jes-jhn20-28": "Entonces Tom\u{e1}s respondi\u{f3}, y d\u{ed}jole: \u{a1}Se\u{f1}or m\u{ed}o, y Dios m\u{ed}o!",
  "jes-heb13-8": "Jesucristo es el mismo ayer, y hoy, y por los siglos.",
  "jes-mar10-45": "Porque el Hijo del hombre tampoco vino para ser servido, mas para servir, y dar su vida en rescate por muchos.",
  "jes-luk19-10": "Porque el Hijo del hombre vino \u{e1} buscar y \u{e1} salvar lo que se hab\u{ed}a perdido.",
  "jes-rev22-13": "Yo soy Alpha y Omega, principio y fin, el primero y el postrero.",
  "fai-heb11-1": "ES pues la fe la sustancia de las cosas que se esperan, la demostraci\u{f3}n de las cosas que no se ven.",
  "fai-heb11-6": "Empero sin fe es imposible agradar \u{e1} Dios; porque es menester que el que \u{e1} Dios se allega, crea que le hay, y que es galardonador de los que le buscan.",
  "fai-rom10-17": "Luego la fe es por el oir; y el oir por la palabra de Dios.",
  "fai-mat17-20": "Y Jes\u{fa}s les dijo: Por vuestra incredulidad; porque de cierto os digo, que si tuviereis fe como un grano de mostaza, dir\u{e9}is \u{e1} este monte: P\u{e1}sate de aqu\u{ed} all\u{e1}: y se pasar\u{e1}: y nada os ser\u{e1} imposible.",
  "fai-2co5-7": "(Porque por fe andamos, no por vista;)",
  "fai-mar9-24": "Y luego el padre del muchacho dijo clamando: Creo, ayuda mi incredulidad.",
  "fai-jas2-17": "As\u{ed} tambi\u{e9}n la fe, si no tuviere obras, es muerta en s\u{ed} misma.",
  "fai-gal2-20": "Con Cristo estoy juntamente crucificado, y vivo, no ya yo, mas vive Cristo en m\u{ed}: y lo que ahora vivo en la carne, lo vivo en la fe del Hijo de Dios, el cual me am\u{f3}, y se entreg\u{f3} \u{e1} s\u{ed} mismo por m\u{ed}.",
  "fai-rom1-17": "Porque en \u{e9}l la justicia de Dios se descubre de fe en fe; como est\u{e1} escrito: Mas el justo vivir\u{e1} por la fe.",
  "fai-mar11-22": "Y respondiendo Jes\u{fa}s, les dice: Tened fe en Dios.",
  "fai-1jn5-4": "Porque todo aquello que es nacido de Dios vence al mundo: y esta es la victoria que vence al mundo, nuestra fe.",
  "fai-heb12-2": "Puestos los ojos en al autor y consumador de la fe, en Jes\u{fa}s; el cual, habi\u{e9}ndole sido propuesto gozo, sufri\u{f3} la cruz, menospreciando la verg\u{fc}enza, y sent\u{f3}se \u{e1} la diestra del trono de Dios.",
  "fai-jas1-6": "Pero pida en fe, no dudando nada: porque el que duda es semejante \u{e1} la onda de la mar, que es movida del viento, y echada de una parte \u{e1} otra.",
  "fai-rom4-20": "Tampoco en la promesa de Dios dud\u{f3} con desconfianza: antes fu\u{e9} esforzado en fe, dando gloria \u{e1} Dios,",
  "rcn-2co5-18": "Y todo esto es de Dios, el cual nos reconcili\u{f3} \u{e1} s\u{ed} por Cristo; y nos di\u{f3} el ministerio de la reconciliaci\u{f3}n.",
  "rcn-2co5-19": "Porque ciertamente Dios estaba en Cristo reconciliando el mundo \u{e1} s\u{ed}, no imput\u{e1}ndole sus pecados, y puso en nosotros la palabra de la reconciliaci\u{f3}n.",
  "rcn-2co5-20": "As\u{ed} que, somos embajadores en nombre de Cristo, como si Dios rogase por medio nuestro; os rogamos en nombre de Cristo: Reconciliaos con Dios.",
  "rcn-rom5-1": "JUSTIFICADOS pues por la fe, tenemos paz para con Dios por medio de nuestro Se\u{f1}or Jesucristo:",
  "rcn-rom5-10": "Porque si siendo enemigos, fuimos reconciliados con Dios por la muerte de su Hijo, mucho m\u{e1}s, estando reconciliados, seremos salvos por su vida.",
  "rcn-col1-20": "Y por \u{e9}l reconciliar todas las cosas \u{e1} s\u{ed}, pacificando por la sangre de su cruz, as\u{ed} lo que est\u{e1} en la tierra como lo que est\u{e1} en los cielos.",
  "rcn-eph2-14": "Porque \u{e9}l es nuestra paz, que de ambos hizo uno, derribando la pared intermedia de separaci\u{f3}n;",
  "rcn-mat5-9": "Bienaventurados los pacificadores: porque ellos ser\u{e1}n llamados hijos de Dios.",
  "rcn-mat5-24": "Deja all\u{ed} tu presente delante del altar, y vete, vuelve primero en amistad con tu hermano, y entonces ven y ofrece tu presente.",
  "rcn-mat18-15": "Por tanto, si tu hermano pecare contra ti, ve, y redarg\u{fa}yele entre ti y \u{e9}l solo: si te oyere, has ganado \u{e1} tu hermano.",
  "rcn-rom12-18": "Si se puede hacer, cuanto est\u{e1} en vosotros, tened paz con todos los hombres.",
  "rcn-heb12-14": "Seguid la paz con todos, y la santidad, sin la cual nadie ver\u{e1} al Se\u{f1}or:",
  "rcn-luk15-20": "Y levant\u{e1}ndose, vino \u{e1} su padre. Y como aun estuviese lejos, vi\u{f3}lo su padre, y fu\u{e9} movido \u{e1} misericordia, y corri\u{f3}, y ech\u{f3}se sobre su cuello, y bes\u{f3}le.",
  "rcn-1pe3-9": "No volviendo mal por mal, ni maldici\u{f3}n por maldici\u{f3}n, sino antes por el contrario, bendiciendo; sabiendo que vosotros sois llamados para que pose\u{e1}is bendici\u{f3}n en herencia.",
  "gd-psa34-8": "Gustad, y ved que es bueno Jehov\u{e1}: dichoso el hombre que confiar\u{e1} en \u{e9}l.",
  "gd-psa100-5": "Porque Jehov\u{e1} es bueno: para siempre es su misericordia, y su verdad por todas las generaciones.",
  "gd-psa145-9": "Bueno es Jehov\u{e1} para con todos; y sus misericordias sobre todas sus obras.",
  "gd-nah1-7": "Bueno es Jehov\u{e1} para fortaleza en el d\u{ed}a de la angustia; y conoce \u{e1} los que en \u{e9}l conf\u{ed}an.",
  "gd-jas1-17": "Toda buena d\u{e1}diva y todo don perfecto es de lo alto, que desciende del Padre de las luces, en el cual no hay mudanza, ni sombra de variaci\u{f3}n.",
  "gd-psa27-13": "Hubiera yo desmayado, si no creyese que tengo de ver la bondad de Jehov\u{e1} en la tierra de los vivientes.",
  "gd-psa86-5": "Porque t\u{fa}, Se\u{f1}or, eres bueno y perdonador, y grande en misericordia para con todos los que te invocan.",
  "gd-psa31-19": "\u{a1}Cu\u{e1}n grande es tu bien, que has guardado para los que te temen, que has obrado para los que esperan en ti, delante de los hijos de los hombres!",
  "gd-rom2-4": "\u{bf}O menosprecias las riquezas de su benignidad, y paciencia, y longanimidad, ignorando que su benignidad te gu\u{ed}a \u{e1} arrepentimiento?",
  "gd-mat7-11": "Pues si vosotros, siendo malos, sab\u{e9}is dar buenas d\u{e1}divas \u{e1} vuestros hijos, \u{bf}cu\u{e1}nto m\u{e1}s vuestro Padre que est\u{e1} en los cielos, dar\u{e1} buenas cosas \u{e1} los que le piden?",
  "gd-psa84-11": "Porque sol y escudo es Jehov\u{e1} Dios: gracia y gloria dar\u{e1} Jehov\u{e1}: no quitar\u{e1} el bien \u{e1} los que en integridad andan.",
  "gd-exo34-6": "Y pasando Jehov\u{e1} por delante de \u{e9}l, proclam\u{f3}: Jehov\u{e1}, Jehov\u{e1}, fuerte, misericordioso, y piadoso; tardo para la ira, y grande en benignidad y verdad;",
  "gd-psa119-68": "Bueno eres t\u{fa}, y bienhechor: ens\u{e9}\u{f1}ame tus estatutos.",
  "gd-psa107-9": "Porque saci\u{f3} al alma menesterosa, y llen\u{f3} de bien al alma hambrienta.",
  "gr-eph2-8": "Porque por gracia sois salvos por la fe; y esto no de vosotros, pues es don de Dios:",
  "gr-eph2-9": "No por obras, para que nadie se glor\u{ed}e.",
  "gr-tit3-5": "No por obras de justicia que nosotros hab\u{ed}amos hecho, mas por su misericordia nos salv\u{f3}, por el lavacro de la regeneraci\u{f3}n, y de la renovaci\u{f3}n del Esp\u{ed}ritu Santo;",
  "gr-act4-12": "Y en ning\u{fa}n otro hay salud; porque no hay otro nombre debajo del cielo, dado \u{e1} los hombres, en que podamos ser salvos.",
  "gr-rom3-24": "Siendo justificados gratuitamente por su gracia, por la redenci\u{f3}n que es en Cristo Jes\u{fa}s;",
  "gr-tit2-11": "Porque la gracia de Dios que trae salvaci\u{f3}n \u{e1} todos los hombres, se manifest\u{f3},",
  "gr-rom5-20": "La ley empero entr\u{f3} para que el pecado creciese; mas cuando el pecado creci\u{f3}, sobrepuj\u{f3} la gracia;",
  "gr-2co8-9": "Porque ya sab\u{e9}is la gracia de nuestro Se\u{f1}or Jesucristo, que por amor de vosotros se hizo pobre, siendo rico; para que vosotros con su pobreza fueseis enriquecidos.",
  "gr-heb4-16": "Llegu\u{e9}monos pues confiadamente al trono de la gracia, para alcanzar misericordia, y hallar gracia para el oportuno socorro.",
  "gr-act16-31": "Y ellos dijeron: Cree en el Se\u{f1}or Jesucristo, y ser\u{e1}s salvo t\u{fa}, y tu casa.",
  "gr-jhn5-24": "De cierto, de cierto os digo: El que oye mi palabra, y cree al que me ha enviado, tiene vida eterna; y no vendr\u{e1} \u{e1} condenaci\u{f3}n, mas pas\u{f3} de muerte \u{e1} vida.",
  "gr-1jn5-13": "Estas cosas he escrito \u{e1} vosotros que cre\u{e9}is en el nombre del Hijo de Dios, para que sep\u{e1}is que ten\u{e9}is vida eterna, y para que cre\u{e1}is en el nombre del Hijo de Dios.",
  "gr-rom8-1": "AHORA pues, ninguna condenaci\u{f3}n hay para los que est\u{e1}n en Cristo Jes\u{fa}s, los que no andan conforme \u{e1} la carne, mas conforme al esp\u{ed}ritu.",
  "gr-isa1-18": "Venid luego, dir\u{e1} Jehov\u{e1}, y estemos \u{e1} cuenta: si vuestros pecados fueren como la grana, como la nieve ser\u{e1}n emblanquecidos: si fueren rojos como el carmes\u{ed}, vendr\u{e1}n \u{e1} ser como blanca lana.",
};
